sql.if:
AND (
    DATE(o.create_time) BETWEEN #{startDate} AND #{endDate}
    OR (o.status IN (2, 3) AND o.close_date BETWEEN #{startDate} AND #{endDate})
)

AND (
    DATE(o2.create_time) BETWEEN #{startDate} AND #{endDate}
    OR (o2.status IN (2, 3) AND o2.close_date BETWEEN #{startDate} AND #{endDate})
)

AND (
    DATE(o3.create_time) BETWEEN #{startDate} AND #{endDate}
    OR (o3.status IN (2, 3) AND o3.close_date BETWEEN #{startDate} AND #{endDate})
)

AND (
    DATE(c.create_time) BETWEEN #{startDate} AND #{endDate}
    OR (c.sign_date IS NOT NULL AND DATE(c.sign_date) BETWEEN #{startDate} AND #{endDate})
    OR (c.end_date IS NOT NULL AND DATE(c.end_date) BETWEEN #{startDate} AND #{endDate})
)

mapper.select:
SELECT u.id AS userId, u.user_name AS userName, d.dept_name AS deptName, COALESCE(o.dealCount, 0) AS dealCount, COALESCE(o.dealAmount, 0) AS dealAmount, COALESCE(c.contractCount, 0) AS contractCount, COALESCE(c.contractAmount, 0) AS contractAmount, COALESCE(pay.receivedAmount, 0) AS receivedAmount, COALESCE(cu.newCustomerCount, 0) AS newCustomerCount FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id LEFT JOIN ( SELECT owner_id, COUNT(*) AS dealCount, SUM(actual_amount) AS dealAmount FROM crm_opportunity WHERE status = 2
AND close_date BETWEEN #{startDate} AND #{endDate}
GROUP BY owner_id ) o ON o.owner_id = u.id LEFT JOIN ( SELECT owner_id, COUNT(*) AS contractCount, SUM(contract_amount) AS contractAmount FROM crm_contract WHERE status = 3
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY owner_id ) c ON c.owner_id = u.id LEFT JOIN ( SELECT c.owner_id, SUM(pr.payment_amount) AS receivedAmount FROM crm_payment_record pr INNER JOIN crm_contract c ON c.id = pr.contract_id WHERE pr.status = 1
AND pr.payment_date BETWEEN #{startDate} AND #{endDate}
GROUP BY c.owner_id ) pay ON pay.owner_id = u.id LEFT JOIN ( SELECT owner_id, COUNT(*) AS newCustomerCount FROM crm_customer WHERE pool_type = 1
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY owner_id ) cu ON cu.owner_id = u.id WHERE u.status = 1
ORDER BY dealAmount DESC

SELECT d.id AS deptId, d.dept_name AS deptName, COALESCE(m.memberCount, 0) AS memberCount, COALESCE(o.dealCount, 0) AS dealCount, COALESCE(o.dealAmount, 0) AS dealAmount, COALESCE(c.contractCount, 0) AS contractCount, COALESCE(c.contractAmount, 0) AS contractAmount, COALESCE(pay.receivedAmount, 0) AS receivedAmount, COALESCE(cu.newCustomerCount, 0) AS newCustomerCount FROM sys_dept d LEFT JOIN ( SELECT dept_id, COUNT(*) AS memberCount FROM sys_user WHERE status = 1 GROUP BY dept_id ) m ON m.dept_id = d.id LEFT JOIN ( SELECT u.dept_id, COUNT(o.id) AS dealCount, SUM(o.actual_amount) AS dealAmount FROM crm_opportunity o INNER JOIN sys_user u ON u.id = o.owner_id AND u.status = 1 WHERE o.status = 2
AND o.owner_id = #{userId}
AND o.close_date BETWEEN #{startDate} AND #{endDate}
GROUP BY u.dept_id ) o ON o.dept_id = d.id LEFT JOIN ( SELECT u.dept_id, COUNT(c.id) AS contractCount, SUM(c.contract_amount) AS contractAmount FROM crm_contract c INNER JOIN sys_user u ON u.id = c.owner_id AND u.status = 1 WHERE c.status = 3
AND c.owner_id = #{userId}
AND DATE(c.create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY u.dept_id ) c ON c.dept_id = d.id LEFT JOIN ( SELECT u.dept_id, SUM(pr.payment_amount) AS receivedAmount FROM crm_payment_record pr INNER JOIN crm_contract c ON c.id = pr.contract_id INNER JOIN sys_user u ON u.id = c.owner_id AND u.status = 1 WHERE pr.status = 1
AND c.owner_id = #{userId}
AND pr.payment_date BETWEEN #{startDate} AND #{endDate}
GROUP BY u.dept_id ) pay ON pay.dept_id = d.id LEFT JOIN ( SELECT u.dept_id, COUNT(cu.id) AS newCustomerCount FROM crm_customer cu INNER JOIN sys_user u ON u.id = cu.owner_id AND u.status = 1 WHERE cu.pool_type = 1
AND cu.owner_id = #{userId}
AND DATE(cu.create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY u.dept_id ) cu ON cu.dept_id = d.id WHERE d.status = 1
AND d.id = (SELECT dept_id FROM sys_user WHERE id = #{userId})
AND (d.id = #{deptId} OR d.dept_path LIKE CONCAT('%/', #{deptId}, '/%') OR d.dept_path LIKE CONCAT('%/', #{deptId}))
AND d.id IN (${scopeDeptIds})
ORDER BY dealAmount DESC

SELECT ROW_NUMBER() OVER (ORDER BY dealAmount DESC) AS rankNum, userId, userName, deptName, dealAmount, dealCount, receivedAmount FROM ( SELECT u.id AS userId, u.user_name AS userName, d.dept_name AS deptName, COALESCE(o.dealAmount, 0) AS dealAmount, COALESCE(o.dealCount, 0) AS dealCount, COALESCE(c.receivedAmount, 0) AS receivedAmount FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id LEFT JOIN ( SELECT owner_id, COUNT(*) AS dealCount, SUM(actual_amount) AS dealAmount FROM crm_opportunity WHERE status = 2
AND close_date BETWEEN #{startDate} AND #{endDate}
GROUP BY owner_id ) o ON o.owner_id = u.id LEFT JOIN ( SELECT c.owner_id, SUM(pr.payment_amount) AS receivedAmount FROM crm_payment_record pr INNER JOIN crm_contract c ON c.id = pr.contract_id WHERE pr.status = 1
AND pr.payment_date BETWEEN #{startDate} AND #{endDate}
GROUP BY c.owner_id ) c ON c.owner_id = u.id WHERE u.status = 1
) t ORDER BY rankNum ASC
LIMIT #{limit}

SELECT 'industry' AS dimension, cu.industry AS value, COUNT(cu.id) AS customerCount, ROUND(COUNT(cu.id) * 100.0 / NULLIF(( SELECT COUNT(cu_all.id) FROM crm_customer cu_all WHERE cu_all.pool_type = 1 AND cu_all.industry IS NOT NULL AND cu_all.industry != ''
), 0), 2) AS percentage FROM crm_customer cu WHERE cu.pool_type = 1 AND cu.industry IS NOT NULL AND cu.industry != ''
GROUP BY cu.industry ORDER BY customerCount DESC

SELECT 'region' AS dimension, cu.province AS value, COUNT(cu.id) AS customerCount, ROUND(COUNT(cu.id) * 100.0 / NULLIF(( SELECT COUNT(cu_all.id) FROM crm_customer cu_all WHERE cu_all.pool_type = 1 AND cu_all.province IS NOT NULL AND cu_all.province != ''
), 0), 2) AS percentage FROM crm_customer cu WHERE cu.pool_type = 1 AND cu.province IS NOT NULL AND cu.province != ''
GROUP BY cu.province ORDER BY customerCount DESC

SELECT 'level' AS dimension, CASE cu.level WHEN 1 THEN '普通' WHEN 2 THEN '重要' WHEN 3 THEN 'VIP' ELSE '未知' END AS value, COUNT(cu.id) AS customerCount, ROUND(COUNT(cu.id) * 100.0 / NULLIF(( SELECT COUNT(cu_all.id) FROM crm_customer cu_all WHERE cu_all.pool_type = 1 AND cu_all.level IS NOT NULL
), 0), 2) AS percentage FROM crm_customer cu WHERE cu.pool_type = 1 AND cu.level IS NOT NULL
GROUP BY cu.level ORDER BY cu.level DESC

SELECT activityLevel, COUNT(customer_id) AS customerCount, ROUND(COUNT(customer_id) * 100.0 / NULLIF(( SELECT COUNT(cu_all.id) FROM crm_customer cu_all WHERE cu_all.pool_type = 1
), 0), 2) AS percentage, ROUND(AVG(follow_count), 0) AS avgFollowCount, ROUND(AVG(days_gap), 0) AS avgDaysSinceLastFollow FROM ( SELECT cu.id AS customer_id, COUNT(f.id) AS follow_count, DATEDIFF(NOW(), MAX(f.create_time)) AS days_gap, CASE WHEN COUNT(f.id) = 0 THEN 'NEVER' WHEN DATEDIFF(NOW(), MAX(f.create_time)) <= 7 THEN 'HIGH' WHEN DATEDIFF(NOW(), MAX(f.create_time)) <= 30 THEN 'MEDIUM' WHEN DATEDIFF(NOW(), MAX(f.create_time)) <= 90 THEN 'LOW' ELSE 'INACTIVE' END AS activityLevel FROM crm_customer cu LEFT JOIN crm_customer_follow f ON f.customer_id = cu.id WHERE cu.pool_type = 1
GROUP BY cu.id ) t GROUP BY activityLevel ORDER BY FIELD(activityLevel, 'HIGH', 'MEDIUM', 'LOW', 'INACTIVE', 'NEVER')

SELECT cu.id AS customerId, cu.customer_name AS customerName, cu.customer_type AS customerType, cu.owner_id AS ownerId, u.user_name AS ownerName, d.dept_name AS deptName, MAX(f.create_time) AS lastFollowTime, DATEDIFF(NOW(), COALESCE(MAX(f.create_time), cu.create_time)) AS daysSinceLastFollow, SUM(c.contract_amount) AS totalContractAmount, CASE WHEN DATEDIFF(NOW(), COALESCE(MAX(f.create_time), cu.create_time)) >= 90 THEN 'HIGH' WHEN DATEDIFF(NOW(), COALESCE(MAX(f.create_time), cu.create_time)) >= 60 THEN 'MEDIUM' ELSE 'LOW' END AS warningLevel FROM crm_customer cu LEFT JOIN crm_customer_follow f ON f.customer_id = cu.id LEFT JOIN crm_contract c ON c.customer_id = cu.id AND c.status = 3 AND c.tenant_id = #{tenantId} LEFT JOIN sys_user u ON u.id = cu.owner_id LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE cu.pool_type = 1
GROUP BY cu.id, cu.customer_name, cu.customer_type, cu.owner_id, cu.create_time, u.user_name, d.dept_name HAVING DATEDIFF(NOW(), COALESCE(MAX(f.create_time), cu.create_time)) >= 30 ORDER BY daysSinceLastFollow DESC
LIMIT #{offset}, #{limit}

SELECT
    s.id AS stageId,
    s.stage_name AS stageName,
    s.sort AS stageOrder,
    COUNT(o.id) AS enterCount,
    (
        SELECT COUNT(o2.id)
        FROM crm_opportunity o2
        INNER JOIN crm_opportunity_stage s2 ON s2.id = o2.stage_id
        WHERE o2.status IN (1, 2)
          AND s2.sort > s.sort
          AND s2.status = 1

         AND s2.tenant_id = #{tenantId} 
         AND o2.owner_id = #{userId} 
         AND o2.dept_id = #{deptId} 
         AND o2.dept_id IN (${scopeDeptIds}) 

    ) AS exitCount,
    ROUND((
        SELECT COUNT(o2.id)
        FROM crm_opportunity o2
        INNER JOIN crm_opportunity_stage s2 ON s2.id = o2.stage_id
        WHERE o2.status IN (1, 2)
          AND s2.sort > s.sort
          AND s2.status = 1

         AND s2.tenant_id = #{tenantId} 
         AND o2.owner_id = #{userId} 
         AND o2.dept_id = #{deptId} 
         AND o2.dept_id IN (${scopeDeptIds}) 

    ) * 100.0 / NULLIF((
        COUNT(o.id) + (
            SELECT COUNT(o3.id)
            FROM crm_opportunity o3
            INNER JOIN crm_opportunity_stage s3 ON s3.id = o3.stage_id
            WHERE o3.status IN (1, 2)
              AND s3.sort > s.sort
              AND s3.status = 1

             AND s3.tenant_id = #{tenantId} 
             AND o3.owner_id = #{userId} 
             AND o3.dept_id = #{deptId} 
             AND o3.dept_id IN (${scopeDeptIds}) 

        )
    ), 0), 2) AS conversionRate,
    ROUND(AVG(CASE WHEN o.id IS NOT NULL THEN DATEDIFF(NOW(), o.update_time) END), 0) AS avgStayDays
FROM crm_opportunity_stage s
LEFT JOIN crm_opportunity o ON o.stage_id = s.id AND o.status IN (1, 2)
     AND o.tenant_id = #{tenantId} 
     AND o.owner_id = #{userId} 
     AND o.dept_id = #{deptId} 
     AND o.dept_id IN (${scopeDeptIds}) 

WHERE s.status = 1

GROUP BY s.id, s.stage_name, s.sort
ORDER BY s.sort ASC

SELECT '管道预测' AS period, SUM(CASE WHEN o.status = 1 AND s.probability >= 70 THEN o.expected_amount ELSE 0 END) AS highProbabilityAmount, SUM(CASE WHEN o.status = 1 AND s.probability BETWEEN 30 AND 69 THEN o.expected_amount ELSE 0 END) AS mediumProbabilityAmount, SUM(CASE WHEN o.status = 1 AND s.probability < 30 THEN o.expected_amount ELSE 0 END) AS lowProbabilityAmount, SUM(CASE WHEN o.status = 1 THEN o.expected_amount * s.probability / 100 ELSE 0 END) AS predictedAmount, COUNT(CASE WHEN o.status = 1 THEN o.id END) AS opportunityCount, SUM(CASE WHEN o.status = 2
AND o.close_date BETWEEN #{startDate} AND #{endDate}
THEN COALESCE(o.actual_amount, o.expected_amount, 0) ELSE 0 END) AS closedAmount FROM crm_opportunity o LEFT JOIN crm_opportunity_stage s ON s.id = o.stage_id WHERE o.status IN (1, 2)

SELECT aging_bucket AS agingRange, aging_name AS agingRangeName, SUM(pending_amount) AS receivableAmount, COUNT(DISTINCT contract_id) AS contractCount, ROUND(SUM(pending_amount) * 100.0 / NULLIF(( SELECT SUM(c_all.contract_amount - c_all.received_amount) FROM crm_contract c_all WHERE c_all.status = 3 AND c_all.contract_amount > c_all.received_amount
AND c_all.owner_id = #{userId} AND c_all.dept_id = #{deptId} AND c_all.dept_id IN (${scopeDeptIds})
AND DATE(c_all.create_time) BETWEEN #{startDate} AND #{endDate}
), 0), 2) AS percentage, risk_level AS riskLevel FROM ( SELECT c.id AS contract_id, c.contract_amount - c.received_amount AS pending_amount, CASE WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 30 THEN '0-30' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 60 THEN '31-60' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 90 THEN '61-90' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 180 THEN '91-180' ELSE '180+' END AS aging_bucket, CASE WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 30 THEN '0-30天' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 60 THEN '31-60天' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 90 THEN '61-90天' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 180 THEN '91-180天' ELSE '180天以上' END AS aging_name, CASE WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 30 THEN 'LOW' WHEN DATEDIFF(NOW(), COALESCE(MIN(pp.plan_date), c.end_date)) <= 90 THEN 'MEDIUM' ELSE 'HIGH' END AS risk_level FROM crm_contract c LEFT JOIN crm_payment_plan pp ON pp.contract_id = c.id AND pp.received_status = 0 AND pp.plan_date < NOW() WHERE c.status = 3 AND c.contract_amount > c.received_amount
GROUP BY c.id, c.contract_amount, c.received_amount, c.end_date ) t GROUP BY aging_bucket, aging_name, risk_level ORDER BY FIELD(aging_bucket, '0-30', '31-60', '61-90', '91-180', '180+')

SELECT
    (SELECT COUNT(id) FROM crm_customer
     WHERE pool_type = 1 AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}

      AND owner_id = #{userId} 
      AND dept_id = #{deptId} 
      AND dept_id IN (${scopeDeptIds}) 
    ) AS newCustomerCount,
    (SELECT SUM(COALESCE(actual_amount, expected_amount, 0)) FROM crm_opportunity
     WHERE status = 2 AND close_date BETWEEN #{startDate} AND #{endDate}

      AND owner_id = #{userId} 
      AND dept_id = #{deptId} 
      AND dept_id IN (${scopeDeptIds}) 
    ) AS dealAmount,
    (SELECT SUM(pr.payment_amount) FROM crm_payment_record pr
     LEFT JOIN crm_contract c ON c.id = pr.contract_id
     WHERE pr.status = 1 AND pr.payment_date BETWEEN #{startDate} AND #{endDate}


      AND c.owner_id = #{userId} 
      AND c.dept_id = #{deptId} 
      AND c.dept_id IN (${scopeDeptIds}) 
    ) AS receivedAmount,
    (SELECT COUNT(DISTINCT cu.id) FROM crm_customer cu
     WHERE cu.pool_type = 1
     AND cu.next_follow_time IS NOT NULL
     AND cu.next_follow_time <= NOW()

      AND cu.owner_id = #{userId} 
      AND cu.dept_id = #{deptId} 
      AND cu.dept_id IN (${scopeDeptIds}) 
    ) AS pendingFollowCount,
    (SELECT COUNT(id) FROM crm_contract
     WHERE status = 3 AND DATEDIFF(end_date, NOW()) BETWEEN 0 AND #{days}

      AND owner_id = #{userId} 
      AND dept_id = #{deptId} 
      AND dept_id IN (${scopeDeptIds}) 
    ) AS expiringContractCount,
    (SELECT COUNT(DISTINCT pp.contract_id) FROM crm_payment_plan pp
     LEFT JOIN crm_contract c ON c.id = pp.contract_id
     WHERE c.status = 3 AND pp.received_status = 0 AND pp.plan_date < NOW()

      AND c.owner_id = #{userId} 
      AND c.dept_id = #{deptId} 
      AND c.dept_id IN (${scopeDeptIds}) 
    ) AS overduePaymentCount,
    (SELECT COUNT(1) FROM (
        SELECT cu.id
        FROM crm_customer cu
        LEFT JOIN crm_customer_follow f ON f.customer_id = cu.id
        WHERE cu.pool_type = 1

         AND cu.owner_id = #{userId} 
         AND cu.dept_id = #{deptId} 
         AND cu.dept_id IN (${scopeDeptIds}) 
        GROUP BY cu.id, cu.create_time
        HAVING DATEDIFF(NOW(), COALESCE(MAX(f.create_time), cu.create_time)) >= 30
     ) churn_t) AS churnWarningCount
